namespace Acme\Module\Kitdemomod\Site\Field;

defined('_JEXEC') or die;

use Acme\Module\Kitdemomod\Site\Helper\AccountLinkHelper;
use Joomla\CMS\Factory;
use Joomla\CMS\Form\FormField;

/**
 * Shows the "Link your account" panel as a field in the module's settings, and
 * answers it. The panel posts back to the module's own edit screen, because
 * Joomla's com_ajax can't reach a site module from the administrator.
 */
class AccountlinkField extends FormField
{
    protected $type = 'Accountlink';

    protected function getInput()
    {
        $app = Factory::getApplication();

        if ($app->getInput()->post->getCmd('account_action', '') !== '') {
            $response = AccountLinkHelper::handleRequest();

            // The edit screen has started rendering around this field; drop it.
            while (ob_get_level() > 0) {
                ob_end_clean();
            }

            header('Content-Type: application/json; charset=utf-8');
            echo $response;

            $app->close();
        }

        return AccountLinkHelper::render();
    }

    protected function getLabel()
    {
        return '';
    }
}
